import {app,BrowserWindow,ipcMain} from 'electron';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
const root=process.env.CLOUDREEL_PACKAGE_ROOT||fileURLToPath(new URL('../../',import.meta.url));
app.setName('CloudReel-Update-UI');app.setPath('userData',process.env.CLOUDREEL_TEST_DIRECTORY);
let window;
const state={settings:{baiduMode:'web',autoSync:false,autoScrape:false},accounts:{baidu:{connected:false},trakt:{connected:false}},items:[],collections:[],logs:[],pendingCount:0,scrape:{running:false},scan:{running:false},scanRoots:[],runtime:{desktop:true,version:'0.3.22',mpvReady:true},player:null,update:{supported:true,phase:'idle',version:null,notes:'',percent:0,error:null,checkedAt:null,total:0,transferred:0}};
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const until=async check=>{for(let i=0;i<150;i++){if(await check())return;await wait(40);}throw Error('UI timeout');};
const calls=[];
app.whenReady().then(async()=>{
  const {createAppUpdater}=await import(pathToFileURL(path.join(root,'electron/services/app-update-runtime.mjs')).href);
  const runtime=path.join(process.env.CLOUDREEL_TEST_DIRECTORY,'installed');fs.mkdirSync(runtime,{recursive:true});
  const fakeApp={isPackaged:true,getVersion:()=> '0.3.22',getPath:()=>path.join(runtime,'CloudReel.exe')};
  assert.equal(createAppUpdater({app:fakeApp}).status().supported,false,'unpacked builds do not self-update');
  fs.writeFileSync(path.join(runtime,'Uninstall CloudReel.exe'),'synthetic uninstaller marker');
  const installed=createAppUpdater({app:fakeApp});assert.equal(installed.status().supported,true);installed.stop();
  assert.equal(createAppUpdater({app:{...fakeApp,isPackaged:false}}).status().supported,false);
  assert.equal(createAppUpdater({app:fakeApp,testChannel:true}).status().supported,false);
  const publish=()=>window.webContents.send('cloudreel:state',structuredClone(state));
  ipcMain.handle('cloudreel:invoke',async(_event,method)=>{calls.push(method);if(method==='update:check'){state.update.phase='checking';publish();await wait(120);state.update={...state.update,phase:'downloading',version:'0.3.23',percent:42,notes:'# 改进\n- 播放与更新更稳定\n<script>invalid</script>'};publish();await wait(300);state.update.phase='downloaded';publish();}if(method==='update:install'){state.update.phase='installing';publish();}return {ok:true,value:structuredClone(state)};});
  window=new BrowserWindow({show:false,width:1380,height:900,webPreferences:{preload:path.join(root,'electron/preload.cjs'),contextIsolation:true,nodeIntegration:false,backgroundThrottling:false,offscreen:true}});
  for(const key of ['show','showInactive','focus'])window[key]=()=>{throw Error('visibility prohibited');};
  await window.loadFile(path.join(root,'dist/index.html'));
  const js=code=>window.webContents.executeJavaScript(code);
  const click=label=>js(`Array.from(document.querySelectorAll('button')).find(button=>button.textContent.trim()===${JSON.stringify(label)}).click()`);
  const capture=async name=>{if(!process.env.CLOUDREEL_UI_OUTPUT)return;fs.mkdirSync(process.env.CLOUDREEL_UI_OUTPUT,{recursive:true});await wait(100);fs.writeFileSync(path.join(process.env.CLOUDREEL_UI_OUTPUT,name),(await window.webContents.capturePage()).toPNG());};
  await until(()=>js("Boolean(document.querySelector('.nav-item'))"));await click('设置');await until(()=>js("Boolean(document.querySelector('.settings-update'))"));
  await click('检查更新');await until(()=>js("Boolean(document.querySelector('.app-update-progress'))"));assert.equal(await js("document.querySelector('.app-update-progress').getAttribute('aria-valuenow')"),'42');assert.equal(await js("document.querySelector('.app-update-row button').disabled"),true);
  await until(()=>js("document.querySelector('.app-update-row button').textContent.includes('重启并更新')"));assert.equal(calls.filter(method=>method==='update:install').length,0);
  await js("document.querySelector('.app-update-notes summary').click()");assert.equal(await js("document.querySelectorAll('.app-update-notes script').length"),0);assert.match(await js("document.querySelector('.app-update-notes p').textContent"),/<script>/);
  await js("document.querySelector('.settings-update').scrollIntoView({block:'center'})");await capture('update-ready.png');state.fileTask={running:true};publish();await until(()=>js("document.querySelector('.app-update-row button').disabled"));assert.match(await js("document.querySelector('.app-update-hint').textContent"),/任务结束/);
  state.fileTask={running:false};publish();await until(()=>js("!document.querySelector('.app-update-row button').disabled"));
  window.setSize(980,680);await wait(100);await js("document.querySelector('.app-update-row button').scrollIntoView({block:'center'})");assert.equal(await js("(()=>{const r=document.querySelector('.app-update-row button').getBoundingClientRect();return r.right<=innerWidth&&r.left>=0;})()"),true);await capture('update-small.png');
  await click('现在观看');await until(()=>js("Boolean(document.querySelector('.app-update-notice'))"));await click('稍后');assert.equal(await js("Boolean(document.querySelector('.app-update-notice'))"),false);
  await click('设置');await until(()=>js("Boolean(document.querySelector('.settings-update'))"));await click('重启并更新');await until(()=>calls.includes('update:install'));assert.equal(calls.filter(method=>method==='update:install').length,1);
  state.update={...state.update,phase:'error',error:'暂时无法检查更新，请稍后重试。'};publish();await until(()=>js("document.querySelector('.app-update-copy p').textContent.includes('暂时无法')"));assert.equal(await js("document.querySelector('.app-update-row button').disabled"),false);
  state.update={...state.update,supported:false,phase:'unsupported',error:null};publish();await until(()=>js("document.querySelector('.app-update-row button').textContent==='查看发布页'"));await click('查看发布页');assert.ok(calls.includes('update:releases'));
  assert.equal(BrowserWindow.getAllWindows().some(view=>view.isVisible()),false);console.log(JSON.stringify({passed:true,checked:true,downloadProgress:true,plainNotes:true,explicitInstall:true,fileOperationGuard:true,responsive:true,visibleWindows:0}));window.destroy();app.quit();
}).catch(error=>{console.error(error.stack);window?.destroy();app.exit(1);});
